import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, UP, DOWN } from '../game/neon.js';

test('Ball should bounce off a brick (top face)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top-left brick

  // Position ball so it's about to hit the bottom of the brick
  // Brick: { x: offsetX, y: BRICK_TOP, w: BRICK_W, h: BRICK_H }
  // Ball: moving UP, hitting the bottom face (y + r > brick.y + brick.h)
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // just below the brick
  state.ball.vy = UP; // moving up
  state.ball.vx = 0;

  // Mock ctx
  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fill: () => {},
    beginPath: () => {},
    fillText: () => {},
  };

  // The frame function should handle the collision
  frame(ctx, state);

  assert.strictEqual(state.ball.vy, DOWN, `Ball should have bounced DOWN after hitting the bottom of the brick, but was ${state.ball.vy}`);
});

import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, UP, DOWN, LEFT, RIGHT } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('D1: No deflection - Ball plows through brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2;
  state.ball.vy = UP;
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, DOWN, 'Ball should bounce DOWN');
});

test('D2: Incorrect axis - Side hit should flip vx, not vy', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball hitting the left side of the brick
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = RIGHT;
  state.ball.vy = 0;
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vx, LEFT, 'Ball should bounce LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should remain 0');
});

test('D3: Stickiness - Ball should not vibrate inside brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball deeply embedded in the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = UP;

  // First frame: should bounce and be pushed OUT
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, DOWN, 'First bounce should be DOWN');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h || state.ball.y + state.ball.r <= brick.y, 'Ball should be pushed out of brick');

  // Second frame: should not collide again if pushed out
  // (we simulate a small movement to see if it's still inside)
  state.ball.y += state.ball.vy * 0.01; 
  frame(mockCtx, state);
  // If it was pushed out, it shouldn't bounce again. If it's still inside, it will flip back to UP.
  assert.strictEqual(state.ball.vy, DOWN, 'Ball should not flip back to UP while moving away');
});

test('D4: Tunneling - Ball should not skip brick at high speed', () => {
  const state = createState(6); // Level 6, speed = 710
  const brick = state.bricks[0];
  brick.alive = true;

  // Ball just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1;
  state.ball.vy = DOWN;
  state.ball.vx = 0;

  // We simulate the physics step’s jump
  // In a real game, this happens in step(), then frame() checks collision.
  // We simulate the result of step(state, 0.05)
  state.ball.y += state.ball.vy * 0.05; // 710 * 0.05 = 35.5. New y = brick.y - 1 + 35.5 = brick.y + 34.5

  frame(mockCtx, state);

  // The ball is now below the brick, but it should have been intercepted.
  // Since frame() only checks current overlap, it will fail to see the collision.
  assert.strictEqual(brick.alive, false, 'Brick should have been broken even if ball jumped over it');
});

