  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = UP;
  frame(mockCtx, state);
  assert.equal(state.ball.vy, DOWN, 'First bounce should be DOWN');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h || state.ball.y + state.ball.r <= brick.y, 'Ball should be pushed out');
  // Move the ball slightly AWAY from the bottom of the brick to avoid Row 1
