  // moving it to 74 should be safe from Row 1 (starts at 76).
  state.ball.y = brick.y + brick.h + state.ball.r - 1; 
  frame(mockCtx, state);
  assert.equal(state.ball.vy, DOWN, 'Ball should not flip back to UP');
});

