// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  frame,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('frame: Ball should bounce off a brick (bottom face)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 10; // Move further down so it doesn't hit Row 1
  state.ball.vy = UP;
  // But wait, if it's too far down, it won't collide with Row 0 anymore.
  // Row 0: [48, 68]. Ball r=7. 
  // For overlap: ball.y - 7 < 68  => ball.y < 75.
  // For no overlap with Row 1: ball.y + 7 < 76 => ball.y < 69.
  // So if ball.y = 70, it overlaps Row 0 and Row 1.
  // If ball.y = 68, it overlaps Row 0 and Row 1 (75 > 76 is false, but 68+7=75 < 76).
  // Wait, if ball.y = 68, then ball.y + r = 75. Row 1 y = 76. 75 < 76. No overlap with Row 1!
  // And ball.y - r = 61. 61 < 68. Overlap with Row 0!
  state.ball.y = 68; 
  frame(mockCtx, state);
  assert.equal(state.ball.vy, DOWN, 'Ball should bounce DOWN');
});

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
