test('frame: Ball should bounce off a brick (side face)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 5; 
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = RIGHT;
  state.ball.vy = 0;
  resolveBrickCollisions(state);
  assert.equal(state.ball.vx, LEFT, 'Ball should bounce LEFT');
  assert.equal(state.ball.vy, 0, 'Ball vy should remain 0');
});

test('frame: Ball should not vibrate inside brick (Stickiness)', () => {
  const state = createState(1);
  state.bricks = [state.bricks[0]];
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vy = UP;
  resolveBrickCollisions(state);
  assert.equal(state.ball.vy, DOWN, 'First bounce should be DOWN');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h || state.ball.y + state.ball.r <= brick.y, 'Ball should be pushed out');
  state.ball.y += state.ball.vy * 0.01; 
  resolveBrickCollisions(state);
  assert.equal(state.ball.vy, DOWN, 'Ball should not flip back to UP');
});

test('frame: Ball should not double-bounce on seam (Ghost)', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  state.ball.x = b1.x + b1.w;
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = RIGHT;
  state.ball.vy = 0;
  resolveBrickCollisions(state);
  assert.equal(state.ball.vx, LEFT, 'Ball should bounce LEFT once');
});

test('step: Ball should not skip brick at high speed (Tunneling)', () => {
  const state = createState(6); 
  const brick = state.bricks[0];
  brick.alive = true;
