  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = DOWN;
  state.ball.vx = 0;

  step(state, 0.05);

  assert.equal(brick.alive, false, 'Brick should have been broken even if ball jumped over it');
});

